import {s,connect,eligible,message} from './accounts.mjs';
export async function initFirebaseLicense(){
let b=null,account=null,stop=null,error='',generation=0;
// This account edition requires a live server check before editing. Inventory stays local.
const access={storageKey:'milai-click-v1',business:null,countId:null,season:null};globalThis.milaiAccess=access;
const live=()=>navigator.onLine&&eligible(account);
access.canWrite=session=>live()&&!session?.completedAt;access.canStart=live;access.acquire=async()=>live();access.finish=async session=>{if(!session.completedAt&&!live())throw Error('החשבון אינו פעיל');return session.completedAt||Date.now()};
const bar=document.createElement('section');bar.className='activation-bar';const label=document.createElement('span'),open=document.createElement('button');open.textContent='החשבון שלי';bar.append(label,open);document.querySelector('main').prepend(bar);
const dialog=document.createElement('dialog');dialog.className='account-dialog';dialog.innerHTML=`<button type="button" class="close" aria-label="סגירה">×</button><div class="account-brand">מלאי בקליק</div><h2>מתחילים לספור</h2><p class="account-intro">כניסה לחשבון קיים או הרשמה לעסק חדש</p><div class="account-tabs" role="tablist" aria-label="פעולה"><button type="button" role="tab" class="tab-login" aria-selected="true">כניסה לחשבון</button><button type="button" role="tab" class="tab-register" aria-selected="false">הרשמה חדשה</button></div><p class="status" role="status" aria-live="polite"></p><form><div class="registration-fields" hidden><label>שם העסק<input name="businessName" maxlength="100" placeholder="לדוגמה: מכולת השכונה" autocomplete="organization"></label><label>מספר עוסק / ח.פ.<input name="number" maxlength="24" inputmode="numeric" placeholder="מספר העסק" dir="ltr"></label></div><label>כתובת אימייל<input name="email" type="email" dir="ltr" placeholder="name@example.com" autocomplete="username" required></label><label>סיסמה<div class="password-row"><input name="password" type="password" autocomplete="current-password" required><button type="button" class="show-password" aria-label="הצגת סיסמה">הצג</button></div></label><small class="password-hint" hidden>בחרו סיסמה של 10 תווים לפחות.</small><button class="primary account-submit" name="action" value="login">כניסה לחשבון</button><button type="button" class="reset">שכחתי סיסמה</button></form><div class="account-signed" hidden><strong>החשבון שלכם</strong><p class="signed-email" dir="ltr"></p><button class="refresh" type="button">בדיקת מצב החשבון</button><button class="logout" type="button">התנתקות</button></div><p class="registration-note" hidden>אחרי ההרשמה, החשבון ממתין לפתיחה על ידי המנהל לאחר בדיקת התשלום.</p><p class="account-footer">הספירות נשמרות במכשיר. נדרש חיבור לאינטרנט לעריכה.</p>`;document.body.append(dialog);
const status=dialog.querySelector('.status'),form=dialog.querySelector('form');
let mode='login';
function setMode(next){mode=next;error='';const register=mode==='register';dialog.querySelector('.registration-fields').hidden=!register;for(const name of ['businessName','number'])form.elements[name].required=register;form.elements.password.minLength=register?10:1;form.elements.password.autocomplete=register?'new-password':'current-password';dialog.querySelector('.password-hint').hidden=!register;dialog.querySelector('.registration-note').hidden=!register;dialog.querySelector('.reset').hidden=register;dialog.querySelector('.account-submit').textContent=register?'יצירת חשבון לעסק':'כניסה לחשבון';dialog.querySelector('.tab-login').setAttribute('aria-selected',String(!register));dialog.querySelector('.tab-register').setAttribute('aria-selected',String(register));status.textContent=register?'מלאו את פרטי העסק כדי ליצור חשבון.':'הזינו את פרטי החשבון שלכם.';}
dialog.querySelector('.tab-login').onclick=()=>setMode('login');dialog.querySelector('.tab-register').onclick=()=>setMode('register');dialog.querySelector('.show-password').onclick=()=>{const input=form.elements.password,show=input.type==='password';input.type=show?'text':'password';dialog.querySelector('.show-password').textContent=show?'הסתר':'הצג'};setMode('login');

function paint(){const active=live();access.business=account?{name:account.businessName,number:account.number}:null;const text=active?'החשבון פעיל עד '+new Date(account.expiresAt).toLocaleString('he-IL'):!navigator.onLine?'אין חיבור — צפייה וגיבוי זמינים':account?.status==='blocked'?'החשבון חסום — פנה למנהל':account?.status==='pending'?'החשבון ממתין לפתיחה לאחר תשלום':account?.status==='active'?'תוקף החשבון הסתיים':b?.auth.currentUser?'כרטיס העסק טרם נוצר. מלא פרטי עסק ולחץ הרשמה':'יש להתחבר לחשבון';label.textContent=text;status.textContent=error||text;const signed=!!b?.auth.currentUser&&!!account;form.hidden=signed;dialog.querySelector('.account-tabs').hidden=signed;dialog.querySelector('.account-signed').hidden=!signed;dialog.querySelector('.signed-email').textContent=b?.auth.currentUser?.email||'';if(signed){dialog.querySelector('.registration-note').hidden=true;dialog.querySelector('h2').textContent='החשבון שלי'}else dialog.querySelector('h2').textContent='מתחילים לספור';bar.dataset.active=String(active);dialog.querySelector('.logout').hidden=!b?.auth.currentUser;document.dispatchEvent(new CustomEvent('milai-license-change'))}
async function ensure(){if(!b)b=await connect();return b}
async function refresh(){const id=++generation;try{await ensure();if(!b.auth.currentUser){account=null;paint();return}const snap=await s.getDocFromServer(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid));if(id!==generation)return;account=snap.exists()?snap.data():null;error='';paint()}catch(e){if(id!==generation)return;account=null;error=message(e);paint()}}
async function listen(){stop?.();await ensure();if(!b.auth.currentUser)return;stop=s.onSnapshot(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),{includeMetadataChanges:true},snap=>{generation++;account=!snap.metadata.fromCache&&snap.exists()?snap.data():null;error='';paint()},e=>{generation++;account=null;error=message(e);paint()})}
form.onsubmit=async event=>{event.preventDefault();const buttons=[...form.querySelectorAll('button')];buttons.forEach(x=>x.disabled=true);try{await ensure();const fields=new FormData(form),email=fields.get('email').trim(),password=fields.get('password');if(mode==='register'){const businessName=fields.get('businessName').trim(),number=fields.get('number').trim();if(!businessName||!number)throw Error('מלא שם עסק ומספר עוסק');if(password.length<10)throw Error('הסיסמה צריכה להכיל לפחות 10 תווים');if(!b.auth.currentUser||b.auth.currentUser.email!==email)await s.createUserWithEmailAndPassword(b.auth,email,password);const ref=s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),old=await s.getDocFromServer(ref);if(!old.exists())await s.setDoc(ref,{uid:b.auth.currentUser.uid,email:b.auth.currentUser.email,businessName,number,status:'pending',expiresAt:0,createdAt:s.serverTimestamp()});}else await s.signInWithEmailAndPassword(b.auth,email,password);await refresh();await listen();if(live())dialog.close()}catch(e){error=message(e);paint()}finally{buttons.forEach(x=>x.disabled=false)}};
open.onclick=()=>{paint();dialog.showModal()};dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('.refresh').onclick=()=>refresh();dialog.querySelector('.logout').onclick=async()=>{generation++;account=null;stop?.();if(b)await s.signOut(b.auth);paint()};dialog.querySelector('.reset').onclick=async()=>{try{await ensure();const email=form.elements.email.value.trim();if(!email)throw Error('הזן אימייל');await s.sendPasswordResetEmail(b.auth,email);status.textContent='אם החשבון קיים, יישלח מייל איפוס'}catch(e){status.textContent=message(e)}};
window.addEventListener('offline',()=>{generation++;account=null;paint()});window.addEventListener('online',async()=>{await refresh();await listen()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});setInterval(()=>{paint();if(navigator.onLine)refresh()},60000);paint();ensure().then(async()=>{await refresh();await listen()}).catch(e=>{error=message(e);paint()});return access;
}
